import Image from "next/image";
import logo from "@/public/logo.webp";
import { cookies } from "next/headers";
import Link from "next/link";
import styles from "./Header.module.scss";
import { jwtVerify } from "jose";
import { db } from "@/src/prisma/db";

export async function Header() {
    const token = (await cookies()).get("token")?.value;
    if(!token) return
    const { payload } = await jwtVerify(token, new TextEncoder().encode(process.env.SECRET_KEY));
    const currentUserId = payload.id;
    const roleCurrentUser = await db.orm.public.Users.where({ id: String(currentUserId) }).select("role").first();

    return (
        <header className={styles.header}>
            <div className={styles.container}>
                <Link href="/" className={styles.logo}>
                    <Image src={logo} alt="Медис" width={36} height={36} />
                    <span>Медис</span>
                </Link>

                <nav className={styles.nav}>
                    <Link className={styles.navLink} href="/services">Услуги</Link>
                    <Link className={styles.navLink} href="/doctors">Врачи</Link>
                    <Link className={styles.navLink} href="/blog">Блог</Link>
                    <Link className={styles.navLink} href="/contacts">Контакты</Link>

                    {token && roleCurrentUser?.role === "admin" && <Link className={styles.btn} href="/admin">Дашбоард</Link>}
                    
                    {token ? (
                        <Link className={styles.btn} href="/profile">Профиль</Link>
                    ) : (
                        <Link className={styles.btn} href="/login">Войти</Link>
                    )}
                </nav>
            </div>
        </header>
    );
}